-- Versioned, literal bank classification rules. No scheduler or new journal path.
CREATE TABLE accounting.bank_rule_revisions(company_id uuid NOT NULL REFERENCES core.companies(id),rule_id uuid NOT NULL,version bigint NOT NULL CHECK(version>0),name text NOT NULL CHECK(length(btrim(name))BETWEEN 1 AND 200),bank_account_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('RECEIVE','PAY')),priority int NOT NULL CHECK(priority BETWEEN 1 AND 10000),enabled boolean NOT NULL,execution_mode text NOT NULL CHECK(execution_mode IN('SUGGEST','AUTO')),definition jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES identity.users(id),PRIMARY KEY(company_id,rule_id,version),FOREIGN KEY(company_id,bank_account_id)REFERENCES accounting.bank_accounts(company_id,id));
CREATE TABLE accounting.bank_rule_previews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),statement_line_id uuid NOT NULL,snapshot jsonb NOT NULL,tax_invoice_reference text,tax_invoice_held_on date,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '15 minutes',created_by uuid NOT NULL REFERENCES identity.users(id),UNIQUE(company_id,id),FOREIGN KEY(company_id,statement_line_id)REFERENCES accounting.bank_statement_lines(company_id,id));
CREATE TABLE accounting.bank_rule_executions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),preview_id uuid NOT NULL,source_document_id uuid NOT NULL,reason text NOT NULL CHECK(length(btrim(reason))BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES identity.users(id),UNIQUE(company_id,id),UNIQUE(company_id,preview_id),UNIQUE(company_id,source_document_id),FOREIGN KEY(company_id,preview_id)REFERENCES accounting.bank_rule_previews(company_id,id),FOREIGN KEY(company_id,source_document_id)REFERENCES accounting.bank_transactions(company_id,id));
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['bank_rule_revisions','bank_rule_previews','bank_rule_executions']LOOP
 EXECUTE format('ALTER TABLE accounting.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE accounting.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY company_scope ON accounting.%I USING(company_id=core.current_company())WITH CHECK(company_id=core.current_company())',t);EXECUTE format('CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON accounting.%I FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation()',t);
END LOOP;END$$;
CREATE INDEX ON accounting.bank_rule_revisions(company_id,bank_account_id,rule_id,version DESC);
CREATE INDEX ON accounting.bank_statement_lines(company_id,bank_account_id,transaction_date,id);
CREATE INDEX ON accounting.bank_rule_previews(company_id,statement_line_id,created_at DESC);
CREATE VIEW accounting.bank_rules WITH(security_invoker=true)AS SELECT DISTINCT ON(company_id,rule_id)* FROM accounting.bank_rule_revisions ORDER BY company_id,rule_id,version DESC;
INSERT INTO identity.permissions(code,description)VALUES('accounting.bank_rules.read','Read rules and bank exceptions'),('accounting.bank_rules.manage','Version, enable and prioritize bank rules'),('accounting.bank_rules.preview','Save explained bank rule previews'),('accounting.bank_rules.execute','Approve one suggested bank classification'),('accounting.bank_rules.auto_execute','Enable or execute automatic bank actions');
CREATE FUNCTION identity.seed_bank_rule_roles(c uuid)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN
 INSERT INTO identity.role_permissions(company_id,role_id,permission_code)SELECT c,r.id,p.code FROM identity.roles r CROSS JOIN identity.permissions p WHERE r.company_id=c AND r.code IN('ADMIN','FINANCE')AND p.code LIKE'accounting.bank_rules.%'AND(p.code<>'accounting.bank_rules.auto_execute'OR r.code='ADMIN')ON CONFLICT DO NOTHING;
END$$;
DO $$DECLARE c uuid;BEGIN FOR c IN SELECT id FROM core.companies LOOP PERFORM set_config('htt.company_id',c::text,true);PERFORM identity.seed_bank_rule_roles(c);END LOOP;PERFORM set_config('htt.company_id','',true);END$$;
CREATE FUNCTION accounting.require_bank_rules(cap text)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN
 PERFORM accounting.require_general_banking('accounting.bank_transactions.read');PERFORM purchase.require_access('accounting.bank_statements.read');PERFORM purchase.require_access('accounting.bank_rules.read');PERFORM purchase.require_access(cap);IF cap='accounting.bank_rules.execute'THEN PERFORM accounting.require_general_banking('accounting.bank_transactions.post');PERFORM accounting.require_general_banking('accounting.bank_transactions.classify');PERFORM purchase.require_access('accounting.bank_statements.match');END IF;
END$$;
CREATE FUNCTION accounting.lock_bank_rules(exclusive_lock boolean)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN
 IF exclusive_lock THEN PERFORM pg_advisory_xact_lock(hashtextextended('bank-rules:'||core.current_company()::text,0));ELSE PERFORM pg_advisory_xact_lock_shared(hashtextextended('bank-rules:'||core.current_company()::text,0));END IF;
END$$;
CREATE FUNCTION accounting.save_bank_rule(p_id uuid,p_version bigint,p_data jsonb)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c uuid:=core.current_company();rid uuid:=coalesce(p_id,gen_random_uuid());old accounting.bank_rule_revisions;line jsonb;cond jsonb:=p_data->'condition';a accounting.accounts;t accounting.tax_codes;pc numeric;total numeric:=0;BEGIN
 PERFORM accounting.require_bank_rules('accounting.bank_rules.manage');PERFORM accounting.lock_bank_rules(true);
 IF p_id IS NOT NULL THEN SELECT*INTO old FROM accounting.bank_rules WHERE company_id=c AND rule_id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'Rule unavailable' USING ERRCODE='HT404';END IF;IF old.version IS DISTINCT FROM p_version THEN RAISE EXCEPTION 'Rule version changed' USING ERRCODE='HR409';END IF;END IF;
 IF p_data->>'executionMode'='AUTO'OR old.execution_mode='AUTO'THEN PERFORM purchase.require_access('accounting.bank_rules.auto_execute');END IF;
 IF p_data IS NULL OR nullif(btrim(p_data->>'name'),'')IS NULL OR length(p_data->>'name')>200 OR coalesce(p_data->>'kind','')NOT IN('PAY','RECEIVE')OR coalesce(p_data->>'executionMode','')NOT IN('SUGGEST','AUTO')OR(p_data->>'priority')IS NULL OR(p_data->>'priority')::int NOT BETWEEN 1 AND 10000 OR jsonb_typeof(p_data->'enabled')IS DISTINCT FROM'boolean'OR jsonb_typeof(cond)IS DISTINCT FROM'object'OR coalesce(cond->>'field','')NOT IN('DESCRIPTION','REFERENCE')OR coalesce(cond->>'operator','')NOT IN('CONTAINS','EQUALS','STARTS_WITH')OR coalesce(length(btrim(cond->>'value')),0)NOT BETWEEN 2 AND 200 OR jsonb_typeof(p_data->'lines')IS DISTINCT FROM'array'OR jsonb_array_length(p_data->'lines')NOT BETWEEN 1 AND 20 THEN RAISE EXCEPTION 'Invalid rule, literal condition or allocations' USING ERRCODE='HR422';END IF;
 IF(cond->>'minGross')IS NOT NULL AND((cond->>'minGross')::numeric<=0 OR(cond->>'minGross')::numeric<>round((cond->>'minGross')::numeric,2))OR(cond->>'maxGross')IS NOT NULL AND((cond->>'maxGross')::numeric<=0 OR(cond->>'maxGross')::numeric<>round((cond->>'maxGross')::numeric,2))OR(cond->>'minGross')::numeric>(cond->>'maxGross')::numeric THEN RAISE EXCEPTION 'Invalid gross amount range' USING ERRCODE='HR422';END IF;
 PERFORM accounting.require_bank_reconciliation_access('accounting.bank_statements.read',(p_data->>'bankAccountId')::uuid);
 FOR line IN SELECT*FROM jsonb_array_elements(p_data->'lines')LOOP
 pc:=(line->>'percent')::numeric;IF coalesce(line->>'basClass','')NOT IN('TAXABLE','EXPORT','OTHER_GST_FREE','INPUT_TAXED','CAPITAL','NON_CAPITAL','EXCLUDED')OR pc IS NULL OR pc<=0 OR pc>100 OR pc<>round(pc,4)OR coalesce(length(btrim(line->>'description')),0)NOT BETWEEN 1 AND 500 OR coalesce(line->>'cashFlowCategory','')NOT IN('OPERATING','INVESTING','FINANCING')OR(line->>'recoverablePercent')IS NULL OR(line->>'recoverablePercent')::numeric NOT BETWEEN 0 AND 100 OR(line->>'recoverablePercent')::numeric<>round((line->>'recoverablePercent')::numeric,4)OR(line->>'inputTaxedPercent')IS NULL OR(line->>'inputTaxedPercent')::numeric NOT BETWEEN 0 AND 100 OR(line->>'inputTaxedPercent')::numeric<>round((line->>'inputTaxedPercent')::numeric,4)THEN RAISE EXCEPTION 'Invalid allocation proportions' USING ERRCODE='HR422';END IF;total:=total+pc;
 SELECT*INTO a FROM accounting.accounts WHERE company_id=c AND id=(line->>'accountId')::uuid AND active AND control_kind IS NULL;IF NOT FOUND OR EXISTS(SELECT 1 FROM accounting.bas_tax_roles WHERE company_id=c AND account_id=a.id)OR EXISTS(SELECT 1 FROM accounting.account_mappings WHERE company_id=c AND account_id=a.id AND purpose IN('CUSTOMER_ADVANCES','SUPPLIER_ADVANCES','PURCHASE_RETURN_CLEARING'))THEN RAISE EXCEPTION 'Rule requires an active non-control offset account' USING ERRCODE='HR422';END IF;
 SELECT*INTO t FROM accounting.tax_codes WHERE company_id=c AND id=(line->>'taxCodeId')::uuid;IF NOT FOUND THEN RAISE EXCEPTION 'Company tax code required' USING ERRCODE='HR422';END IF;
 IF p_data->>'kind'='PAY'THEN
 IF NOT((a.kind='EXPENSE'AND line->>'basClass'IN('NON_CAPITAL','EXCLUDED'))OR(a.kind='ASSET'AND line->>'basClass'IN('CAPITAL','EXCLUDED'))OR(a.kind IN('LIABILITY','EQUITY')AND line->>'basClass'='EXCLUDED'))OR(line->>'basClass'='EXCLUDED'AND t.category<>'OUT_OF_SCOPE')THEN RAISE EXCEPTION 'Payment account and BAS purpose conflict' USING ERRCODE='HR422';END IF;
 ELSE
 IF(line->>'recoverablePercent')::numeric<>0 OR(line->>'inputTaxedPercent')::numeric<>0 OR NOT((a.kind='REVENUE'AND((t.category='TAXABLE'AND line->>'basClass'='TAXABLE')OR(t.category='GST_FREE'AND line->>'basClass'IN('EXPORT','OTHER_GST_FREE'))OR(t.category='INPUT_TAXED'AND line->>'basClass'='INPUT_TAXED')OR(t.category='OUT_OF_SCOPE'AND line->>'basClass'='EXCLUDED')))OR(a.kind IN('ASSET','LIABILITY','EQUITY')AND t.category='OUT_OF_SCOPE'AND line->>'basClass'='EXCLUDED'))THEN RAISE EXCEPTION 'Receipt account and BAS purpose conflict' USING ERRCODE='HR422';END IF;END IF;
 END LOOP;
 IF total<>100 THEN RAISE EXCEPTION 'Allocation percentages must total 100' USING ERRCODE='HR422';END IF;
 INSERT INTO accounting.bank_rule_revisions(company_id,rule_id,version,name,bank_account_id,kind,priority,enabled,execution_mode,definition,created_by)VALUES(c,rid,coalesce(old.version,0)+1,btrim(p_data->>'name'),(p_data->>'bankAccountId')::uuid,p_data->>'kind',(p_data->>'priority')::int,(p_data->>'enabled')::boolean,p_data->>'executionMode',p_data,core.current_actor());RETURN rid;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RAISE EXCEPTION 'Invalid typed rule value' USING ERRCODE='HR422';END$$;
-- Evaluation is a read-only statement snapshot. Execution always re-evaluates under locks.
CREATE FUNCTION accounting.evaluate_bank_rules(p_line uuid,p_evidence text DEFAULT NULL,p_held date DEFAULT NULL)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c uuid:=core.current_company();l accounting.bank_statement_lines;st accounting.bank_statement_controls;r accounting.bank_rule_revisions;co core.companies;x jsonb;a accounting.accounts;t accounting.tax_codes;rate numeric;part numeric;allocated numeric:=0;n numeric;tax numeric;rec numeric;idx int:=0;items jsonb:='[]';matches jsonb;ruleset jsonb;outcome text;note text;used numeric;candidate uuid;facts jsonb:='[]';BEGIN
 PERFORM accounting.require_bank_rules('accounting.bank_rules.read');SELECT*INTO l FROM accounting.bank_statement_lines WHERE company_id=c AND id=p_line;IF NOT FOUND THEN RAISE EXCEPTION 'Statement line unavailable' USING ERRCODE='HT404';END IF;
 SELECT*INTO st FROM accounting.bank_statement_controls WHERE company_id=c AND id=l.statement_id;SELECT*INTO co FROM core.companies WHERE id=c;
 SELECT coalesce(jsonb_agg(jsonb_build_array(rule_id,version)ORDER BY rule_id),'[]')INTO ruleset FROM accounting.bank_rules WHERE company_id=c AND bank_account_id=l.bank_account_id;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',q.rule_id,'version',q.version,'priority',q.priority,'name',q.name,'executionMode',q.execution_mode,'condition',q.definition->'condition')ORDER BY q.priority,q.rule_id),'[]')INTO matches FROM accounting.bank_rules q WHERE q.company_id=c AND q.bank_account_id=l.bank_account_id AND q.enabled AND(q.kind='RECEIVE')=(l.amount>0)AND((q.definition->'condition'->>'minGross')IS NULL OR abs(l.amount)>=(q.definition->'condition'->>'minGross')::numeric)AND((q.definition->'condition'->>'maxGross')IS NULL OR abs(l.amount)<=(q.definition->'condition'->>'maxGross')::numeric)AND CASE q.definition->'condition'->>'operator'WHEN'EQUALS'THEN lower(CASE q.definition->'condition'->>'field'WHEN'REFERENCE'THEN l.reference ELSE l.description END)=lower(q.definition->'condition'->>'value')WHEN'CONTAINS'THEN strpos(lower(CASE q.definition->'condition'->>'field'WHEN'REFERENCE'THEN l.reference ELSE l.description END),lower(q.definition->'condition'->>'value'))>0 WHEN'STARTS_WITH'THEN starts_with(lower(CASE q.definition->'condition'->>'field'WHEN'REFERENCE'THEN l.reference ELSE l.description END),lower(q.definition->'condition'->>'value'))ELSE false END;
 SELECT coalesce(sum(b.amount),0)INTO used FROM accounting.active_bank_matches m JOIN accounting.bank_match_allocations b ON b.company_id=m.company_id AND b.match_id=m.id WHERE m.company_id=c AND m.statement_line_id=l.id;
 IF st.state<>'OPEN'THEN outcome:='STATEMENT_CLOSED';ELSIF used>=abs(l.amount)THEN outcome:='MATCHED';ELSIF used>0 THEN outcome:='PARTIALLY_MATCHED';
 ELSIF EXISTS(SELECT 1 FROM accounting.bank_transactions b WHERE b.company_id=c AND b.statement_line_id=l.id AND NOT EXISTS(SELECT 1 FROM accounting.bank_transaction_reversals v WHERE v.company_id=c AND v.original_id=b.id))THEN outcome:='SOURCE_ALREADY_POSTED';
 ELSIF jsonb_array_length(matches)=0 THEN outcome:='NO_RULE';ELSIF jsonb_array_length(matches)>1 AND matches->0->>'priority'=matches->1->>'priority'THEN outcome:='AMBIGUOUS_RULE';
 ELSIF NOT EXISTS(SELECT 1 FROM accounting.periods p WHERE p.company_id=c AND p.state='OPEN'AND p.starts_on<=l.transaction_date AND p.ends_on>l.transaction_date)THEN outcome:='ACCOUNTING_PERIOD_CLOSED';
 ELSIF EXISTS(SELECT 1 FROM accounting.bas_periods p JOIN accounting.bas_period_controls s ON s.company_id=p.company_id AND s.id=p.id WHERE p.company_id=c AND s.state<>'OPEN'AND p.from_date<=l.transaction_date AND p.to_date>l.transaction_date)THEN outcome:='BAS_FROZEN';
 ELSIF EXISTS(SELECT 1 FROM accounting.active_bank_reconciliations br WHERE br.company_id=c AND br.bank_account_id=l.bank_account_id AND br.to_date>=l.transaction_date)THEN outcome:='BANK_CUTOFF';
 ELSIF NOT EXISTS(SELECT 1 FROM accounting.bank_accounts b JOIN accounting.accounts g ON g.company_id=b.company_id AND g.id=b.id JOIN accounting.cash_flow_scopes cs ON cs.company_id=b.company_id AND cs.bank_account_id=b.id WHERE b.company_id=c AND b.id=l.bank_account_id AND b.active AND g.active AND NOT cs.review_required)THEN outcome:='BANK_REVIEW_REQUIRED';
 ELSIF co.gst_registered IS NULL OR co.gst_basis IS NULL THEN outcome:='TAX_CONFIGURATION_REQUIRED';END IF;
 IF outcome IS NULL THEN
 SELECT p.id INTO candidate FROM accounting.bank_cash_positions p WHERE p.company_id=c AND p.bank_account_id=l.bank_account_id AND sign(p.signed_amount)=sign(l.amount)AND p.amount-p.reserved_amount=abs(l.amount)AND p.posting_date<=l.transaction_date AND NOT EXISTS(SELECT 1 FROM accounting.bank_transaction_reversals v WHERE v.company_id=c AND p.source_document_id IN(v.id,v.original_id))ORDER BY p.posting_date,p.id LIMIT 1;
 IF candidate IS NOT NULL THEN outcome:='EXISTING_CASH_MATCH';END IF;END IF;
 IF jsonb_array_length(matches)>0 THEN SELECT*INTO r FROM accounting.bank_rules WHERE company_id=c AND rule_id=(matches->0->>'id')::uuid;END IF;
 IF outcome IS NULL THEN
 FOR x IN SELECT*FROM jsonb_array_elements(r.definition->'lines')LOOP
 idx:=idx+1;part:=CASE WHEN idx=jsonb_array_length(r.definition->'lines')THEN abs(l.amount)-allocated ELSE round(abs(l.amount)*(x->>'percent')::numeric/100,2)END;allocated:=allocated+part;
 SELECT*INTO a FROM accounting.accounts WHERE company_id=c AND id=(x->>'accountId')::uuid;SELECT*INTO t FROM accounting.tax_codes WHERE company_id=c AND id=(x->>'taxCodeId')::uuid;
 SELECT z.rate INTO rate FROM accounting.tax_rates z WHERE z.company_id=c AND z.tax_code_id=t.id AND z.effective_from<=l.transaction_date AND(z.effective_to IS NULL OR z.effective_to>l.transaction_date)ORDER BY z.effective_from DESC LIMIT 1;
 IF a.id IS NULL OR NOT a.active OR a.control_kind IS NOT NULL OR EXISTS(SELECT 1 FROM accounting.bas_tax_roles WHERE company_id=c AND account_id=a.id)OR EXISTS(SELECT 1 FROM accounting.account_mappings WHERE company_id=c AND account_id=a.id AND purpose IN('CUSTOMER_ADVANCES','SUPPLIER_ADVANCES','PURCHASE_RETURN_CLEARING'))OR rate IS NULL OR(t.category='TAXABLE'AND rate<>0.1)OR(NOT co.gst_registered AND t.category<>'OUT_OF_SCOPE')THEN outcome:='INVALID_ACTION';EXIT;END IF;
 tax:=CASE WHEN t.category='TAXABLE'THEN round(part/11,2)ELSE 0 END;n:=part-tax;rec:=CASE WHEN r.kind='PAY'THEN round(tax*(x->>'recoverablePercent')::numeric/100,2)ELSE 0 END;
 IF n<=0 OR(t.category='TAXABLE'AND tax<>round(n*rate,2))THEN outcome:='AMOUNT_ROUNDING';EXIT;END IF;
 IF r.kind='PAY'AND(NOT((a.kind='EXPENSE'AND x->>'basClass'IN('NON_CAPITAL','EXCLUDED'))OR(a.kind='ASSET'AND x->>'basClass'IN('CAPITAL','EXCLUDED'))OR(a.kind IN('LIABILITY','EQUITY')AND x->>'basClass'='EXCLUDED'))OR(x->>'basClass'='EXCLUDED'AND(tax<>0 OR t.category<>'OUT_OF_SCOPE')))OR r.kind='RECEIVE'AND NOT((a.kind='REVENUE'AND((t.category='TAXABLE'AND x->>'basClass'='TAXABLE')OR(t.category='GST_FREE'AND x->>'basClass'IN('EXPORT','OTHER_GST_FREE'))OR(t.category='INPUT_TAXED'AND x->>'basClass'='INPUT_TAXED')OR(t.category='OUT_OF_SCOPE'AND x->>'basClass'='EXCLUDED')))OR(a.kind IN('ASSET','LIABILITY','EQUITY')AND t.category='OUT_OF_SCOPE'AND x->>'basClass'='EXCLUDED'))THEN outcome:='INVALID_ACTION';EXIT;END IF;
 IF(CASE WHEN r.kind='PAY'THEN rec ELSE tax END)>0 AND NOT EXISTS(SELECT 1 FROM accounting.tax_account_mappings m JOIN accounting.accounts g ON g.company_id=m.company_id AND g.id=CASE WHEN r.kind='PAY'THEN m.input_account_id ELSE m.output_account_id END WHERE m.company_id=c AND m.tax_code_id=t.id AND g.active AND g.control_kind='GST'AND g.kind=CASE WHEN r.kind='PAY'THEN'ASSET'ELSE'LIABILITY'END)THEN outcome:='INVALID_ACTION';EXIT;END IF;

 items:=items||jsonb_build_array(jsonb_build_object('accountId',a.id,'description',x->>'description','net',n::text,'tax',tax::text,'recoverableTax',rec::text,'taxCodeId',t.id,'basClass',x->>'basClass','cashFlowCategory',x->>'cashFlowCategory','inputTaxedPercent',(x->>'inputTaxedPercent')::numeric));
 facts:=facts||jsonb_build_array(jsonb_build_object('account',to_jsonb(a),'taxCode',to_jsonb(t),'rate',rate,'mapping',(SELECT to_jsonb(m)FROM accounting.tax_account_mappings m WHERE m.company_id=c AND m.tax_code_id=t.id),'gstAccounts',(SELECT jsonb_agg(to_jsonb(g)ORDER BY g.id)FROM accounting.accounts g JOIN accounting.tax_account_mappings m ON m.company_id=g.company_id AND g.id IN(m.input_account_id,m.output_account_id)WHERE m.company_id=c AND m.tax_code_id=t.id)));
 END LOOP;
 IF outcome IS NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(items)e WHERE(e->>'recoverableTax')::numeric>0)AND(p_evidence IS NULL OR p_held IS NULL)THEN outcome:='NEEDS_TAX_EVIDENCE';END IF;
 IF outcome IS NULL AND((p_evidence IS NULL)IS DISTINCT FROM(p_held IS NULL)OR p_held>l.transaction_date OR p_held<'0002-01-01'OR p_evidence IS NOT NULL AND length(btrim(p_evidence))NOT BETWEEN 1 AND 500 OR co.gst_basis='NON_CASH'AND p_held IS NOT NULL AND p_held<>l.transaction_date)THEN outcome:='INVALID_TAX_EVIDENCE';END IF;
 END IF;
 RETURN jsonb_build_object('statementLineId',l.id,'statementId',l.statement_id,'statementVersion',st.version,'bankAccountId',l.bank_account_id,'occurredOn',l.transaction_date,'description',l.description,'reference',l.reference,'gross',abs(l.amount)::text,'remaining',(abs(l.amount)-used)::text,'kind',CASE WHEN l.amount>0 THEN'RECEIVE'ELSE'PAY'END,'status',coalesce(outcome,'READY'),'candidates',matches,'selectedRuleId',r.rule_id,'selectedRuleVersion',r.version,'executionMode',r.execution_mode,'lines',items,'existingCashLineId',candidate,'ruleset',ruleset,'facts',facts,'bankConfiguration',jsonb_build_object('bank',(SELECT to_jsonb(b)FROM accounting.bank_accounts b WHERE b.company_id=c AND b.id=l.bank_account_id),'scope',(SELECT to_jsonb(cs)FROM accounting.cash_flow_scopes cs WHERE cs.company_id=c AND cs.bank_account_id=l.bank_account_id)),'gstBasis',co.gst_basis,'gstRegistered',co.gst_registered);
END$$;
CREATE FUNCTION accounting.preview_bank_rule(p_line uuid,p_evidence text,p_held date)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c uuid:=core.current_company();b uuid;result jsonb;pid uuid;BEGIN
 PERFORM accounting.require_bank_rules('accounting.bank_rules.preview');PERFORM accounting.bas_lock(c,false);PERFORM accounting.lock_bank_rules(false);
 SELECT bank_account_id INTO b FROM accounting.bank_statement_lines WHERE company_id=c AND id=p_line;IF NOT FOUND THEN RAISE EXCEPTION 'Statement line unavailable' USING ERRCODE='HT404';END IF;PERFORM accounting.lock_bank_reconciliation(b);
 result:=accounting.evaluate_bank_rules(p_line,p_evidence,p_held);INSERT INTO accounting.bank_rule_previews(company_id,statement_line_id,snapshot,tax_invoice_reference,tax_invoice_held_on,created_by)VALUES(c,p_line,result,p_evidence,p_held,core.current_actor())RETURNING id INTO pid;RETURN pid;
END$$;
CREATE FUNCTION accounting.execute_bank_rule(p_preview uuid,p_confirm boolean,p_reason text)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c uuid:=core.current_company();p accounting.bank_rule_previews;current_result jsonb;source_id uuid;result_id uuid;BEGIN
 PERFORM accounting.require_bank_rules('accounting.bank_rules.execute');PERFORM accounting.require_general_banking('accounting.bank_transactions.post');PERFORM accounting.require_general_banking('accounting.bank_transactions.classify');PERFORM purchase.require_access('accounting.bank_statements.match');
 PERFORM accounting.bas_lock(c,false);PERFORM accounting.lock_bank_rules(false);SELECT*INTO p FROM accounting.bank_rule_previews WHERE company_id=c AND id=p_preview;IF NOT FOUND THEN RAISE EXCEPTION 'Preview unavailable' USING ERRCODE='HT404';END IF;
 IF p.snapshot->>'executionMode'='AUTO'THEN PERFORM purchase.require_access('accounting.bank_rules.auto_execute');END IF;
 PERFORM accounting.lock_bank_reconciliation((p.snapshot->>'bankAccountId')::uuid);
 IF p_confirm IS DISTINCT FROM true OR coalesce(length(btrim(p_reason)),0)NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Explicit no-prior-posting confirmation and execution reason required' USING ERRCODE='HR422';END IF;
 IF p.expires_at<=clock_timestamp()OR p.snapshot->>'status'<>'READY'OR EXISTS(SELECT 1 FROM accounting.bank_rule_executions WHERE company_id=c AND preview_id=p.id)THEN RAISE EXCEPTION 'Preview expired, blocked or already executed' USING ERRCODE='HR409';END IF;
 current_result:=accounting.evaluate_bank_rules(p.statement_line_id,p.tax_invoice_reference,p.tax_invoice_held_on);IF current_result IS DISTINCT FROM p.snapshot OR current_result->>'status'<>'READY'THEN RAISE EXCEPTION 'Preview changed; refresh rules, evidence and statement' USING ERRCODE='HR409';END IF;
 source_id:=accounting.post_general_banking(current_result->>'kind',(current_result->>'bankAccountId')::uuid,NULL,(current_result->>'occurredOn')::date,'RULE-'||p.id::text,p_reason,current_result->'lines',NULL,NULL,true,p.tax_invoice_reference,p.tax_invoice_held_on,p.statement_line_id,(current_result->>'statementVersion')::bigint);
 INSERT INTO accounting.bank_rule_executions(company_id,preview_id,source_document_id,reason,created_by)VALUES(c,p.id,source_id,btrim(p_reason),core.current_actor())RETURNING id INTO result_id;RETURN result_id;
END$$;
CREATE FUNCTION accounting.validate_bank_rule_execution()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN
 IF NOT EXISTS(SELECT 1 FROM accounting.bank_rule_executions e JOIN accounting.bank_rule_previews p ON p.company_id=e.company_id AND p.id=e.preview_id JOIN accounting.bank_transactions b ON b.company_id=e.company_id AND b.id=e.source_document_id WHERE e.company_id=NEW.company_id AND e.id=NEW.id AND b.statement_line_id=p.statement_line_id AND b.reference='RULE-'||p.id::text AND b.gross=(p.snapshot->>'gross')::numeric AND b.kind=p.snapshot->>'kind'AND p.snapshot->>'status'='READY')THEN RAISE EXCEPTION 'Rule execution/source invariant failed' USING ERRCODE='23514';END IF;RETURN NULL;
END$$;
CREATE CONSTRAINT TRIGGER source_proof AFTER INSERT ON accounting.bank_rule_executions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION accounting.validate_bank_rule_execution();
REVOKE ALL ON FUNCTION identity.seed_bank_rule_roles(uuid),accounting.require_bank_rules(text),accounting.lock_bank_rules(boolean),accounting.save_bank_rule(uuid,bigint,jsonb),accounting.evaluate_bank_rules(uuid,text,date),accounting.preview_bank_rule(uuid,text,date),accounting.execute_bank_rule(uuid,boolean,text),accounting.validate_bank_rule_execution()FROM PUBLIC;
GRANT SELECT ON accounting.bank_rule_revisions,accounting.bank_rules,accounting.bank_rule_previews,accounting.bank_rule_executions TO htt_app;
GRANT EXECUTE ON FUNCTION accounting.require_bank_rules(text),accounting.lock_bank_rules(boolean),accounting.save_bank_rule(uuid,bigint,jsonb),accounting.evaluate_bank_rules(uuid,text,date),accounting.preview_bank_rule(uuid,text,date),accounting.execute_bank_rule(uuid,boolean,text)TO htt_app;
